#include <cctype>
#include <string>

void toUpperInPlace(std::string& text)
{
    for (char& c : text)
    {
        c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
    }
}

std::string shout(const std::string& text)
{
    std::string copy{ text };
    toUpperInPlace(copy);
    return copy + "!";
}

unitTests:
TEST("toUpperInPlace changes the caller's string") { std::string s{ "hello there" }; toUpperInPlace(s); CHECK_EQ(s, "HELLO THERE"); }
TEST("digits and punctuation are untouched") { std::string s{ "c++ 20, ok?" }; toUpperInPlace(s); CHECK_EQ(s, "C++ 20, OK?"); }
TEST("shout returns a new string") { const std::string quiet{ "look out" }; CHECK_EQ(shout(quiet), "LOOK OUT!"); CHECK_EQ(quiet, "look out"); }
TEST("shout of nothing") { CHECK_EQ(shout(""), "!"); }

